    fn readonly_version_upper_bound_inductive(pre: Self, post: Self, rid: ReqId) { admit(); }

    #[inductive(readonly_ready_to_read)]
    fn readonly_ready_to_read_inductive(pre: Self, post: Self, rid: ReqId, node_id: NodeId) { admit(); }

    #[inductive(readonly_apply)]
    fn readonly_apply_inductive(pre: Self, post: Self, rid: ReqId) {
        assert(pre.inv_read_results());
        assert forall |r| #[trigger] post.local_reads.contains_key(r)
            implies post.read_results_match(post.local_reads[r]) by {
            if r == rid {
                match pre.local_reads[rid] {
                    ReadonlyState::ReadyToRead { op, node_id, version_upper_bound } => {
                        assert(post.local_reads[r] == ReadonlyState::Done {
                            op, node_id, version_upper_bound,
                            ret: DT::dispatch_spec(pre.replicas[node_id], op),
                        });
                        assert(pre.replicas[node_id] == compute_nrstate_at_version(
                            pre.log, pre.current_local_version(node_id)));
                        assert(pre.current_local_version(node_id) == pre.local_versions[node_id]);
                        assert(version_upper_bound <= pre.current_local_version(node_id));
                        assert(pre.local_versions[node_id] <= pre.version_upper_bound);
                        assert(exists |v: nat| rangeincl(version_upper_bound, v, post.version_upper_bound)
                            && DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op)
                                == DT::dispatch_spec(pre.replicas[node_id], op)) by {
                            assert(rangeincl(version_upper_bound, pre.current_local_version(node_id),
                                post.version_upper_bound));
                            assert(post.log === pre.log);
                            assert(post.version_upper_bound == pre.version_upper_bound);
                            assert(post.current_local_version(node_id)
                                == pre.current_local_version(node_id));
                            let v = pre.current_local_version(node_id);
                            assert(forall |i| 0 <= i < v ==> post.log.contains_key(i));
                            assert(forall |i| 0 <= i < v ==> post.log[i] == pre.log[i]);
                            compute_nrstate_at_version_preserves(post.log, pre.log, v);
                            assert(compute_nrstate_at_version(post.log, v)
                                == compute_nrstate_at_version(pre.log, v));
                            assert(DT::dispatch_spec(compute_nrstate_at_version(post.log, v), op)
                                == DT::dispatch_spec(pre.replicas[node_id], op));
                            assert(exists |x: nat| rangeincl(version_upper_bound, x, post.version_upper_bound)
                                && DT::dispatch_spec(compute_nrstate_at_version(post.log, x), op)
                                    == DT::dispatch_spec(pre.replicas[node_id], op)) by {
                            }
                        }
                    },
                    _ => { assert(false); }
                }
            } else {
                assert(post.local_reads[r] == pre.local_reads[r]);
                assert(pre.read_results_match(pre.local_reads[r]));
                assert(post.read_results_match(post.local_reads[r]));
            }
        } 
    }

